+// specific language governing permissions and limitations
+// under the License.
+
+import ballerina/io;
+
+function combine(int a, int b = 10, int c = 20, int d = a * 100 + b, int e = c - a) returns int[] {
+    return [a, b, c, d, e];
+}
+
+function applyTo(function (int) returns int f, int x = 1, int y = 2, int z = f(x + y)) returns int {
+    return z;
+}
+
+function capture(int a, string s = "-", function () returns string g = () => s + a.toString()) returns string {
+    return g();
+}
+
+type Shifter function (int base, int step = 1, int scale = 3, int shifted = base * scale) returns int;
+
+class Counter {
+    function next(int first, int step = 1, int count = 5, int last = first + count) returns int[] {
+        return [first, step, count, last];
+    }
+}
+
+function withRest(int a, int b = 4, int c = a + a, int... rest) returns int {
+    return a + b + c + rest.length();
+}
+
+public function main() {
+    io:println(combine(1)); // @output [1,10,20,110,19]
+    io:println(combine(2, 3)); // @output [2,3,20,203,18]
+    io:println(combine(2, c = 7)); // @output [2,10,7,210,5]
+    io:println(combine(a = 3, e = 0)); // @output [3,10,20,310,0]
+
+    io:println(applyTo(n => n * 2)); // @output 6
+    io:println(applyTo(n => n * 2, 5)); // @output 14
+    io:println(applyTo(n => n * 2, y = 0)); // @output 2
+
+    io:println(capture(7)); // @output -7
+    io:println(capture(7, "#")); // @output #7
+
+    Shifter shift = function (int base, int step = 1, int scale = 3, int shifted = base * scale) returns int {
+        return shifted + step;
+    };
+    io:println(shift(4)); // @output 13
+    io:println(shift(4, scale = 10)); // @output 41
+
+    Counter counter = new;
+    io:println(counter.next(2)); // @output [2,1,5,7]
+    io:println(counter.next(2, count = 9)); // @output [2,1,9,11]
+
+    io:println(withRest(3)); // @output 13
+    io:println(withRest(3, 1, 0, 9, 9)); // @output 6
+}
