+type paramRefCollector struct {
+	t            typeResolver
+	paramIndices map[model.SymbolRef]int
+	limit        int
+	refs         []int
+}
+
+func (c *paramRefCollector) Visit(node ast.BLangNode) ast.Visitor {
+	var symbol model.SymbolRef
+	switch n := node.(type) {
+	case *ast.BLangInvocation:
+		// A method call still carries a deferred method symbol; its receiver is reached as a child node.
+		ref, ok := n.RawSymbol.(*model.SymbolRef)
+		if !ok || ref == nil {
+			return c
+		}
+		symbol = *ref
+	case ast.BNodeWithSymbol:
+		symbol = n.Symbol()
+	default:
+		return c
+	}
+	if idx, ok := c.paramIndices[c.t.unnarrowedSymbol(symbol)]; ok && idx < c.limit {
+		c.refs = append(c.refs, idx)
+	}
+	return c
+}
+
+func (c *paramRefCollector) VisitTypeData(_ *ast.TypeData) ast.Visitor { return c }
+
+// referencedPrecedingParams returns, sorted and without duplicates, the indices in
+// paramIndices below limit of the parameter symbols expr refers to, or nil if there are none.
+func referencedPrecedingParams(t typeResolver, expr ast.BLangNode, paramIndices map[model.SymbolRef]int, limit int) []int {
+	c := &paramRefCollector{t: t, paramIndices: paramIndices, limit: limit}
+	ast.Walk(c, expr)
+	if len(c.refs) == 0 {
+		return nil
+	}
+	sort.Ints(c.refs)
+	refs := c.refs[:1]
+	for _, idx := range c.refs[1:] {
+		if idx != refs[len(refs)-1] {
+			refs = append(refs, idx)
+		}
+	}
+	return refs
+}
